#!/usr/bin/env python3
"""seagent compat shim for a Hermes Python plugin (generated by `seagent-plugin::compat`).

Speaks seagent's plugin protocol v1 -- MCP JSON-RPC 2.0 over stdio, one object per
line, no Content-Length framing (crates/seagent-plugin/src/plugin.rs,
crates/seagent-plugin/src/transport.rs) -- and loads the Hermes plugin package that
sits next to this file's source directory:

  initialize            -> MCP capabilities + seagent extras (hooks, commands)
  tools/list, tools/call-> the plugin's `provides_tools` / ctx.register_tool
  seagent/hook {event,payload} -> on_<hook> / hook_<hook> / _on_<hook> or the
                             callbacks the plugin registered through
                             register(ctx); anything missing or failing is
                             {"decision":"allow"} (a broken plugin never blocks
                             the agent), the failure goes to stderr
  seagent/command {name,args}  -> ctx.register_command handlers
  ping / resources/list / prompts/list / shutdown

Standard library only (sys, json, os, importlib).
"""
import importlib.util
import json
import os
import sys

ID = __ID__
PLUGIN_DIR = os.environ.get("SEAGENT_PLUGIN_DIR") or __PLUGIN_DIR__
PKG = __PKG__
# seagent hook event -> the Hermes hook names to look for, in order (baked from
# `provides_hooks` through seagent_kernel::hooks::HookEvent::parse).
HOOKS = __HOOKS__
# `provides_tools` from plugin.yaml.
TOOLS = __TOOLS__
# Events whose payload field is a text the handler may rewrite by returning a
# string (seagent PluginHook maps `result`/`output`/`text` to the protocol's `input`).
TRANSFORM_EVENTS = ("transform_tool_result", "transform_terminal_output", "transform_llm_output", "transform_api_error")

MOD = None
CTX = None
HANDLERS = {}
LOAD_ERROR = ""


def log(msg):
    try:
        sys.stderr.write("seagent-compat[%s]: %s\n" % (ID, msg))
        sys.stderr.flush()
    except Exception:
        pass


class Ctx:
    """The subset of the Hermes plugin context that can be honoured here."""

    def __init__(self):
        self.hooks = {}
        self.tools = {}
        self.commands = {}

    def register_hook(self, name, fn=None):
        if callable(fn):
            self.hooks.setdefault(str(name), []).append(fn)

    def register_tool(self, name, fn=None, **kw):
        handler = fn if callable(fn) else kw.get("handler")
        self.tools.setdefault(str(name), {"fn": handler if callable(handler) else None, "description": str(kw.get("description") or kw.get("help") or "")})

    def register_command(self, name, fn=None, **kw):
        handler = fn if callable(fn) else kw.get("handler")
        self.commands.setdefault(str(name).lstrip("/"), {"fn": handler if callable(handler) else None, "description": str(kw.get("description") or kw.get("help") or "")})

    def get_config(self, key, default=None):
        """Hermes `PluginContext.get_config` returns the DEFAULT when unset (plugins do
        `int(ctx.get_config("timeout", 180))`), so never return None here."""
        return default

    def get(self, key, default=None):
        return default

    def __getattr__(self, name):
        # Unknown registration APIs (register_cli_command, register_provider,
        # register_dashboard_auth, ...) are accepted and dropped: they have no
        # seagent equivalent here, and refusing them would abort the whole plugin.
        if name.startswith("__"):
            raise AttributeError(name)

        def _noop(*a, **k):
            return None

        return _noop


def hermes_root():
    """The Hermes checkout the plugin lives in (`hermes_constants`, `tools.*`, `agent.*`).

    Real plugins import the Hermes runtime, not just their own package; without the checkout
    on sys.path every such import fails and the plugin loads empty. SEAGENT_HERMES_ROOT wins."""
    env = os.environ.get("SEAGENT_HERMES_ROOT")
    if env and os.path.isdir(env):
        return env
    d = os.path.abspath(PLUGIN_DIR)
    for _ in range(5):
        parent = os.path.dirname(d)
        if not parent or parent == d:
            break
        d = parent
        if os.path.isfile(os.path.join(d, "hermes_constants.py")):
            return d
        if os.path.isdir(os.path.join(d, "hermes_cli")) and os.path.isfile(os.path.join(d, "pyproject.toml")):
            return d
    return None


def load():
    """Import the plugin package from PLUGIN_DIR (never raises)."""
    global MOD, CTX
    init = os.path.join(PLUGIN_DIR, "__init__.py")
    if not os.path.isfile(init):
        raise RuntimeError("no __init__.py in %s" % PLUGIN_DIR)
    spec = importlib.util.spec_from_file_location(PKG, init, submodule_search_locations=[PLUGIN_DIR])
    if spec is None or spec.loader is None:
        raise RuntimeError("cannot import %s" % init)
    mod = importlib.util.module_from_spec(spec)
    sys.modules[PKG] = mod
    root = hermes_root()
    if root and root not in sys.path:
        sys.path.insert(0, root)
    if PLUGIN_DIR not in sys.path:
        sys.path.insert(0, PLUGIN_DIR)
    spec.loader.exec_module(mod)
    MOD = mod
    ctx = Ctx()
    register = getattr(mod, "register", None)
    if callable(register):
        register(ctx)
    CTX = ctx
    collect(mod, ctx)


def collect(mod, ctx):
    global HANDLERS
    handlers = {}
    for name, fns in ctx.hooks.items():
        handlers.setdefault(name, []).extend(fns)
    for _event, names in HOOKS:
        for n in names:
            for attr in ("hook_" + n, "on_" + n, "_on_" + n):
                fn = getattr(mod, attr, None)
                if callable(fn) and fn not in handlers.get(n, []):
                    handlers.setdefault(n, []).append(fn)
    HANDLERS = handlers


def hook_events():
    out = []
    for event, names in HOOKS:
        if any(HANDLERS.get(n) for n in names):
            out.append(event)
    return out


def tool_names():
    names = list(TOOLS)
    for n in (CTX.tools if CTX else {}):
        if n not in names:
            names.append(n)
    return names


def hermes_kwargs(payload):
    """seagent's hook payload -> the keyword names Hermes handlers take.

    seagent sends the kernel payload (`tool_name`, `tool_input`, `tool_response`,
    `prompt`, `session_id`, `cwd`) plus the protocol's `input` (the part a hook may
    rewrite). Hermes handlers take `tool_name` / `args` / `result`.
    """
    kw = dict(payload) if isinstance(payload, dict) else {}
    if "args" not in kw:
        for k in ("tool_input", "input"):
            if k in kw:
                kw["args"] = kw[k]
                break
    if "result" not in kw:
        for k in ("tool_response", "input", "output"):
            if k in kw:
                kw["result"] = kw[k]
                break
    return kw


def call_flexible(fn, payload):
    """Hermes hooks take keyword fields (`tool_name`, `args`, ...); fall back on the payload."""
    if isinstance(payload, dict):
        try:
            return fn(**hermes_kwargs(payload))
        except TypeError:
            pass
    try:
        return fn(payload)
    except TypeError:
        return fn()


def decision_of(result, transform=False):
    if result is None:
        return {"decision": "allow"}
    if isinstance(result, str) and transform:
        # Hermes transform hooks return the replacement text.
        return {"decision": "modify", "input": result}
    if not isinstance(result, dict):
        log("hook returned %s (no seagent directive); allowing" % type(result).__name__)
        return {"decision": "allow"}
    act = result.get("decision")
    if act in ("allow", "deny", "modify"):
        out = {"decision": act}
        if isinstance(result.get("reason"), str):
            out["reason"] = result["reason"]
        if "input" in result:
            out["input"] = result["input"]
        return out
    action = str(result.get("action") or "").strip().lower()
    if action in ("block", "deny") or result.get("blocked") is True:
        msg = result.get("message") or result.get("reason") or "blocked by plugin"
        return {"decision": "deny", "reason": msg if isinstance(msg, str) else "blocked by plugin"}
    if action == "modify":
        args = result.get("args", result.get("tool_input", result.get("input")))
        if isinstance(args, dict):
            return {"decision": "modify", "input": args}
        log("modify directive without a dict payload; allowing")
        return {"decision": "allow"}
    if isinstance(result.get("context"), str) and result["context"].strip():
        log("hook `context` has no seagent equivalent and was dropped")
    return {"decision": "allow"}


def text_content(value):
    if isinstance(value, str):
        return value
    try:
        return json.dumps(value, default=str)
    except Exception:
        return str(value)


def handle(method, params):
    if method == "initialize":
        caps = {}
        if tool_names():
            caps["tools"] = {}
        commands = []
        for name, spec in (CTX.commands if CTX else {}).items():
            commands.append({"name": name, "description": spec.get("description", ""), "args": ""})
        seagent = {"version": 1, "hooks": hook_events(), "commands": commands}
        caps["experimental"] = {"seagent": seagent}
        pv = params.get("protocolVersion")
        return {"protocolVersion": pv if isinstance(pv, str) and pv else "2025-11-25", "capabilities": caps, "serverInfo": {"name": ID, "version": "compat-shim"}}
    if method == "ping":
        return {}
    if method == "shutdown":
        return {}
    if method == "tools/list":
        tools = []
        for n in tool_names():
            spec = (CTX.tools.get(n) if CTX else None) or {}
            tools.append({"name": n, "description": spec.get("description", "") or ("Hermes plugin tool %s" % n), "inputSchema": {"type": "object", "additionalProperties": True}})
        return {"tools": tools}
    if method == "tools/call":
        name = params.get("name") or ""
        args = params.get("arguments") or {}
        fn = ((CTX.tools.get(name) or {}) if CTX else {}).get("fn") or getattr(MOD, name, None)
        if not callable(fn):
            return {"content": [{"type": "text", "text": "tool %s is declared but not exported by the plugin" % name}], "isError": True}
        if not isinstance(args, dict):
            args = {"value": args}
        try:
            return {"content": [{"type": "text", "text": text_content(fn(**args))}]}
        except Exception as e:
            return {"content": [{"type": "text", "text": "tool %s failed: %r" % (name, e)}], "isError": True}
    if method == "seagent/hook":
        event = params.get("event") or ""
        payload = params.get("payload") or {}
        names = []
        for ev, candidates in HOOKS:
            if ev == event:
                names = candidates
                break
        fns = []
        for n in names:
            fns.extend(HANDLERS.get(n, []))
        if not fns and event:
            fns.extend(HANDLERS.get(event, []))
        out = {"decision": "allow"}
        for fn in fns:
            try:
                d = decision_of(call_flexible(fn, payload), event in TRANSFORM_EVENTS)
            except Exception as e:
                log("hook %s failed (allowing): %r" % (event, e))
                continue
            if d.get("decision") != "allow":
                return d
            out = d
        return out
    if method == "seagent/command":
        name = str(params.get("name") or "").lstrip("/")
        fn = ((CTX.commands.get(name) or {}) if CTX else {}).get("fn") or getattr(MOD, "cmd_" + name, None)
        if not callable(fn):
            return {"text": "command `%s` is not available in this plugin" % name}
        try:
            argv = params.get("args")
            r = fn(argv) if isinstance(argv, str) and argv else fn()
            return {"text": text_content(r)} if r is not None else {}
        except Exception as e:
            log("command %s failed: %r" % (name, e))
            return {"text": "command `%s` failed: %r" % (name, e)}
    if method == "resources/list":
        return {"resources": []}
    if method == "prompts/list":
        return {"prompts": []}
    raise LookupError(method)


def reply(mid, result):
    sys.stdout.write(json.dumps({"jsonrpc": "2.0", "id": mid, "result": result}) + "\n")
    sys.stdout.flush()


def fail(mid, code, message):
    sys.stdout.write(json.dumps({"jsonrpc": "2.0", "id": mid, "error": {"code": code, "message": message}}) + "\n")
    sys.stdout.flush()


def main():
    global LOAD_ERROR
    try:
        load()
    except Exception as e:
        # Keep serving: seagent asks this shim for declarations, and "no hooks, no
        # tools" is a truthful answer for a plugin that cannot load here.
        LOAD_ERROR = repr(e)
        log("plugin failed to load (%s); serving an empty plugin" % LOAD_ERROR)
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        try:
            msg = json.loads(line)
        except ValueError:
            log("ignoring a line that is not JSON")
            continue
        if not isinstance(msg, dict):
            continue
        mid = msg.get("id")
        method = msg.get("method")
        if method is None:
            continue
        if mid is None:
            if method == "exit":
                return 0
            continue  # notification
        try:
            reply(mid, handle(str(method), msg.get("params") or {}))
        except LookupError as e:
            fail(mid, -32601, "method not found: %s" % e)
        except Exception as e:
            log("request %s failed: %r" % (method, e))
            fail(mid, -32603, repr(e))
    return 0


if __name__ == "__main__":
    sys.exit(main())
